import * as React from 'react';

export interface ChipContextValue {
  disabled: boolean;
}

export const ChipContext = React.createContext<ChipContextValue | undefined>(
  undefined,
);

export const useChipContext = (): ChipContextValue | undefined =>
  React.useContext(ChipContext);
